// === Tab: mySketch ===
let epiColors; // https://github.com/epibyte/p5-epi-colors
let S, shapes;

function setup() {
	createCanvas(windowWidth, windowHeight, P2D);
	S = ~~(max(width, height) / 11);
	frameRate(60);

	background(128);
	stroke("deeppink");
	strokeWeight(1);
	noStroke();
	noFill();

	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();
	// console.log(epiColors);

	init();
}

function init() {
	epiColors.getRandomPalette();

	//
	shapes = [];
	// 
	const spHori = sqrt(3) * S;
	const spVert = 3/2 * S;
	for (let y = 0, j = 0; y < height+spVert/2; y += spVert, j++) {
		for (let x = j % 2 == 0 ? spHori/2 : 0, i = 0; x < width+spHori/2; x += spHori, i++) {
			nshape(x, y, S);
			// hexagons.push( {x, y, r: S} );
		}
	}
	shuffle(shapes, true);

	loop();
}

function draw() {
	//
	if (!shapes.length) init();

	const sh = shapes.shift();
	fill(epiColors.getRandomClr());
	triangle(sh.p1.x, sh.p1.y, sh.p2.x, sh.p2.y, sh.p3.x, sh.p3.y);
}

function nshape(x, y, r, n = 6) {
	let a = TAU/n/2;
	const da = TAU/n;
	const pts = [];
	pts.push( { x, y } );
	// beginShape();
	for (let i = 0; i < n; i++) {
		const vx = x + cos(a) * r;
		const vy = y + sin(a) * r;
		// vertex(vx, vy);
		pts.push( { x: vx, y: vy } );
		// if (i == 0) circle(vx, vy, 5);
		a += da;
	}
	// endShape(CLOSE);

	shapes.push( { p1: pts[6], p2: pts[1], p3: pts[2] } );
	shapes.push( { p1: pts[6], p2: pts[0], p3: pts[2] } );
	shapes.push( { p1: pts[2], p2: pts[3], p3: pts[4] } );
	shapes.push( { p1: pts[2], p2: pts[0], p3: pts[4] } );
	shapes.push( { p1: pts[4], p2: pts[5], p3: pts[6] } );
	shapes.push( { p1: pts[4], p2: pts[0], p3: pts[6] } );
}

function windowResized() {
	resizeCanvas(innerWidth, innerHeight);
	init();
}
